 for i=1,2 do f[i].meter=math.min(100,f[i].meter+.045)end
 remaining=math.max(0,remaining-1/60)
 for i=1,2 do if ready(i) then f[i].face=f[3-i].x>=f[i].x and 1 or -1 end end
 local a,b=f[1],f[2]
 for i=1,2 do withControl(i,function()
  local p=f[i]
